      "var": "regular packages",
      "coef": 1.0
     },
     {
      "var": "premium packages",
      "coef": -1.0
     }
    ],
    "sense": "<=",
    "rhs": -1.0
   },
   {
    "name": "minimum regular packages",
    "terms": [
     {
      "var": "regular packages",
      "coef": 1.0
     }
    ],
    "sense": ">=",
    "rhs": 15.0
   }
  ]
 },
 "facts": {
